    "bypassChannelMembers": {
      "type": "array",
      "items": {
        "type": "string"
      },
      "description": "Names (or employee numbers) of assigned channel members the user wants to bypass/skip for this grievance, matched against the chosen template's channel member list. Optional - omit to keep every channel member in the escalation chain. Show the user the full channel member list (returned as soon as the template is resolved) before they ask to bypass anyone. At least one channel member must always remain un-bypassed - naming every assigned member is rejected with \"You are not allowed to bypass all the channels in grievance application.\" (confirmed via Beacon's own validation message, type 'Grievance', key 'GrCannotByPassAllChannels'). If the user asks to bypass everyone, tell them one member must stay and ask them to leave at least one in."
    },
    "confirmed": {
      "type": "boolean",
      "description": "Set true only after the user has seen the preview this tool returns (ground, template, channel members and any bypassed ones, summary, description, hide-identity, mood, attachments) and has explicitly agreed to submit. Omit or set false to preview without submitting anything - this is the default and safe to call repeatedly while the user is still deciding."
    },
    "isAudioRecorded": {
      "type": "boolean",
      "description": "Controls whether audio recording is requested. Send true when the user explicitly asks to record, capture, or save audio. Otherwise, always send false by default. Always include this field in the tool input.",
      "enum": [
        true,
        false
      ],
      "default": false
    }
  },
  "required": [
    "templateName",
    "ground",
    "summary",
    "description",
    "moodRating",
    "isAudioRecorded"
  ]
}

